namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your day right with these morning favorites", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Midday meals that are quick and satisfying", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty evening dishes for the whole family", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Quick bites for any time of day", Icon = "🍿" },
        };

        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast", Ingredients = "2 cups flour\n2 eggs\n1 cup milk\n2 tbsp sugar\n1 tsp baking powder", Steps = "1. Mix dry ingredients\n2. Whisk eggs and milk\n3. Combine wet and dry\n4. Cook on griddle until golden", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Caesar Salad", Category = "Lunch", Ingredients = "Romaine lettuce\nCroutons\nParmesan cheese\nCaesar dressing\nGrilled chicken", Steps = "1. Chop romaine lettuce\n2. Grill and slice chicken\n3. Toss lettuce with dressing\n4. Top with croutons and parmesan", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner", Ingredients = "400g spaghetti\n500g ground beef\n1 onion\n2 cloves garlic\n400ml tomato sauce\nOlive oil\nSalt and pepper", Steps = "1. Cook spaghetti al dente\n2. Sauté onion and garlic\n3. Brown the ground beef\n4. Add tomato sauce and simmer 20 min\n5. Serve sauce over pasta", AverageRating = 4.8, RatingCount = 20 },
            new() { Id = 4, Title = "Chocolate Brownies", Category = "Desserts", Ingredients = "200g dark chocolate\n150g butter\n3 eggs\n200g sugar\n100g flour\n1 tsp vanilla", Steps = "1. Melt chocolate and butter\n2. Whisk eggs and sugar\n3. Fold in chocolate mixture\n4. Add flour and vanilla\n5. Bake at 350°F for 25 min", AverageRating = 4.9, RatingCount = 15 },
            new() { Id = 5, Title = "Trail Mix Energy Bites", Category = "Snacks", Ingredients = "1 cup oats\n1/2 cup peanut butter\n1/3 cup honey\n1/2 cup chocolate chips\n1/4 cup dried cranberries", Steps = "1. Mix all ingredients\n2. Refrigerate 30 minutes\n3. Roll into small balls\n4. Store in fridge", AverageRating = 4.0, RatingCount = 6 },
            new() { Id = 6, Title = "Avocado Toast", Category = "Breakfast", Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\nLemon juice", Steps = "1. Toast bread until golden\n2. Mash avocado with lemon juice\n3. Spread on toast\n4. Season with salt, pepper, and red pepper flakes", AverageRating = 4.3, RatingCount = 10 },
        };
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public List<Recipe> GetAllRecipes() => _recipes;

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int rating)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && rating >= 1 && rating <= 5)
        {
            var totalRating = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalRating + rating) / recipe.RatingCount;
        }
    }
}

