@page "/category/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category yet. <a href="/submit">Submit one!</a></p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<RecipeHub.Models.Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeHub</PageTitle>
    <h1>Recipe not found</h1>
    <p><a href="/">Return to homepage</a></p>
}
else
{
    <PageTitle>@recipe.Title - RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@recipe.Category.ToLower()">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: @recipe.Category</p>

    <div class="row">
        <div class="col-md-8">
            <div class="card mb-4">
                <div class="card-header"><h3 class="mb-0">Ingredients</h3></div>
                <div class="card-body">
                    <ul class="list-unstyled">
                        @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                        {
                            <li>• @ingredient</li>
                        }
                    </ul>
                </div>
            </div>

            <div class="card mb-4">
                <div class="card-header"><h3 class="mb-0">Steps</h3></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n'))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>

        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><h3 class="mb-0">Rating</h3></div>
                <div class="card-body">
                    <p>Average: ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>
                    <StarRating RecipeId="@recipe.Id" />
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="mt-3">
    <p class="mb-2">Rate this recipe:</p>
    <div style="font-size: 1.5rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => Rate(star)"
                  @onmouseover="() => hoverRating = star"
                  @onmouseout="() => hoverRating = 0"
                  style="color: @(GetStarColor(star))">
                @(star <= GetDisplayRating() ? "★" : "☆")
            </span>
        }
    </div>
    @if (submitted)
    {
        <div class="alert alert-success mt-2" role="alert">
            Thanks! You rated this @selectedRating/5 stars.
        </div>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int hoverRating;
    private int selectedRating;
    private bool submitted;

    private int GetDisplayRating() => hoverRating > 0 ? hoverRating : selectedRating;

    private string GetStarColor(int star) =>
        star <= GetDisplayRating() ? "#ffc107" : "#dee2e6";

    private void Rate(int rating)
    {
        selectedRating = rating;
        submitted = true;
        RecipeService.RateRecipe(RecipeId, rating);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe submitted!</h4>
        <p>Your recipe "<strong>@newRecipe.Title</strong>" has been added to the @newRecipe.Category category.</p>
        <a href="/category/@newRecipe.Category.ToLower()" class="btn btn-primary">View Category</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <EditForm Model="newRecipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
                <DataAnnotationsValidator />

                <div class="mb-3">
                    <label for="title" class="form-label">Recipe Title</label>
                    <InputText id="title" class="form-control" @bind-Value="newRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label for="category" class="form-label">Category</label>
                    <InputSelect id="category" class="form-select" @bind-Value="newRecipe.Category">
                        <option value="">-- Select a category --</option>
                        @foreach (var cat in RecipeService.GetCategories())
                        {
                            <option value="@cat.Name">@cat.Name</option>
                        }
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label for="ingredients" class="form-label">Ingredients</label>
                    <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="newRecipe.Ingredients" placeholder="One ingredient per line" />
                    <div class="form-text">Enter one ingredient per line</div>
                </div>

                <div class="mb-3">
                    <label for="steps" class="form-label">Steps</label>
                    <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="newRecipe.Steps" placeholder="One step per line" />
                    <div class="form-text">Enter one step per line</div>
                </div>

                <button type="submit" class="btn btn-success"
                        disabled="@(string.IsNullOrWhiteSpace(newRecipe.Title) || string.IsNullOrWhiteSpace(newRecipe.Category))">
                    Submit Recipe
                </button>
            </EditForm>
        </div>
    </div>
}

@code {
    private Recipe newRecipe = new();
    private bool submitted;

    private void HandleSubmit()
    {
        if (!string.IsNullOrWhiteSpace(newRecipe.Title) && !string.IsNullOrWhiteSpace(newRecipe.Category))
        {
            RecipeService.AddRecipe(newRecipe);
            submitted = true;
        }
    }

    private void Reset()
    {
        newRecipe = new Recipe();
        submitted = false;
    }
}

